{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://migaia.dev/rpc/protocol.schema.json",
  "title": "migaia.rpc/2 semantic protocol",
  "$comment": "Self-contained JSON projection of rpc-contract ./protocol. Native binary/carrier extension shells are separate boundaries. Preserve object own-key order during encode/decode; schema does not sort data. JSON Schema checks representable structural constraints only; authoritative pure validators enforce all semantic admission. Fixed protocol records ignore unknown fields (core ); portable byte tags and method-schema definitions retain their own admission rules.",
  "oneOf": [
    {
      "$ref": "#/$defs/hello"
    },
    {
      "$ref": "#/$defs/accept"
    },
    {
      "$ref": "#/$defs/admissionPending"
    },
    {
      "$ref": "#/$defs/reject"
    },
    {
      "$ref": "#/$defs/call"
    },
    {
      "$ref": "#/$defs/group"
    },
    {
      "$ref": "#/$defs/result"
    },
    {
      "$ref": "#/$defs/error"
    },
    {
      "$ref": "#/$defs/cancel"
    },
    {
      "$ref": "#/$defs/stream"
    },
    {
      "$ref": "#/$defs/outcomeFrame"
    },
    {
      "$ref": "#/$defs/control"
    },
    {
      "$ref": "#/$defs/directoryFrame"
    }
  ],
  "$defs": {
    "identifier": {
      "type": "string",
      "minLength": 1,
      "maxLength": 128
    },
    "uint": {
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "generation": {
      "type": "object",
      "required": [
        "kind",
        "value",
        "providerId"
      ],
      "properties": {
        "kind": {
          "enum": [
            "restart",
            "session"
          ]
        },
        "value": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "providerId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        }
      }
    },
    "route": {
      "type": "object",
      "required": [
        "applicationVersion",
        "senderId",
        "targetId",
        "receiverId",
        "sentAt"
      ],
      "properties": {
        "applicationVersion": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        },
        "senderId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        },
        "targetId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        },
        "receiverId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128
        },
        "sentAt": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "forwardRoute": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^[0-9a-f]{32}$"
          },
          "minItems": 2,
          "maxItems": 17
        },
        "remainingMs": {
          "type": "number",
          "minimum": 0,
          "maximum": 2147483647
        },
        "trace": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256,
          "pattern": "^[ -~]+$"
        }
      }
    },
    "portable": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "type": "boolean"
        },
        {
          "type": "number"
        },
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/portable"
          },
          "minItems": 0
        },
        {
          "type": "object",
          "propertyNames": {
            "not": {
              "const": "$rpc"
            }
          },
          "additionalProperties": {
            "$ref": "#/$defs/portable"
          }
        },
        {
          "type": "object",
          "required": [
            "$rpc",
            "base64url"
          ],
          "properties": {
            "$rpc": {
              "const": "bytes"
            },
            "base64url": {
              "type": "string",
              "pattern": "^([A-Za-z0-9_-]{4})*([A-Za-z0-9_-][AQgw]|[A-Za-z0-9_-]{2}[AEIMQUYcgkosw048])?$"
