      "$ref": "#/$defs/result"
    },
    {
      "$ref": "#/$defs/error"
    },
    {
      "$ref": "#/$defs/cancel"
    },
    {
      "$ref": "#/$defs/stream"
    },
    {
      "$ref": "#/$defs/outcomeFrame"
    },
    {
