          "additionalProperties": {
            "$ref": "#/$defs/portable"
          }
        },
        {
          "type": "object",
          "required": [
            "$rpc",
            "base64url"
          ],
          "properties": {
            "$rpc": {
              "const": "bytes"
            },
            "base64url": {
              "type": "string",
              "pattern": "^([A-Za-z0-9_-]{4})*([A-Za-z0-9_-][AQgw]|[A-Za-z0-9_-]{2}[AEIMQUYcgkosw048])?$"
            }
          },
          "additionalProperties": false
        }
      ]
    },
    "methodSchema": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
