            "type": "string"
          }
        },
        "items": {
          "$ref": "#/$defs/methodSchema"
        },
        "enum": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/portable"
          }
        },
        "const": {
          "$ref": "#/$defs/portable"
        },
        "anyOf": {
          "type": "array",
          "minItems": 1,
          "items": {
