    "extensionList": {
      "type": "array",
      "maxItems": 64,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/extension"
      }
    },
    "extensions": {
      "type": "object",
      "propertyNames": {
        "$ref": "#/$defs/extension"
      },
      "additionalProperties": {
        "$ref": "#/$defs/portable"
      }
    },
    "codec": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9.-]{0,31}$"
    },
    "directory": {
      "type": "object",
      "required": [
        "schemaVersion",
        "self",
        "methods"
      ],
      "properties": {
        "schemaVersion": {
          "const": 3
        },
        "self": {
          "type": "object",
          "required": [
            "name",
            "instanceId",
            "generation"
          ],
          "properties": {
            "name": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "instanceId": {
              "type": "string",
              "minLength": 1,
              "maxLength": 128
            },
            "generation": {
              "$ref": "#/$defs/generation"
