              "supportedModes",
              "modeSource"
            ],
            "properties": {
              "name": {
                "type": "string",
                "maxLength": 128,
                "pattern": "^[A-Za-z][A-Za-z0-9_-]{0,39}(\\.[A-Za-z][A-Za-z0-9_-]{0,39})*$"
              },
